package dev.toka.profiles;

import com.google.gson.*;
import dev.toka.profiles.migration.*;
import dev.toka.profiles.storage.*;
import dev.toka.storage.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import static org.junit.Assert.*;

public class StagedMigrationTest {
 @Test public void interruptedBatchCanResumeWithoutDuplicateRecords()throws Exception{var root=root();var rows=new JsonArray();for(int i=1;i<=20;i++)rows.add(row(i,"Fixture"+i,UUID.randomUUID()));Path source=root.resolve("source.json"),stage=root.resolve("stage");Files.writeString(source,rows.toString());var job=StagedProfileMigration.startAsync(source,Backend.SQLITE,stage,1,500);boolean checkpoint=false;for(int i=0;i<100;i++){Path manifest=stage.resolve("manifest.json");if(Files.exists(manifest)&&JsonParser.parseString(Files.readString(manifest)).getAsJsonObject().get("completed").getAsInt()>0){checkpoint=true;break;}Thread.sleep(20);}assertTrue(checkpoint);assertTrue(job.cancel(true));StagedProfileMigration.Result result=null;for(int i=0;i<100;i++){try{result=StagedProfileMigration.run(source,Backend.SQLITE,stage,5,0,new JsonArray());break;}catch(java.nio.channels.OverlappingFileLockException busy){Thread.sleep(20);}}assertNotNull(result);assertEquals("ready",result.status());assertEquals(20,result.completed());StagedProfileMigration.verifyReady(stage,source,Backend.SQLITE);}
 private JsonObject row(int id,String name,UUID uuid){var r=new JsonObject();r.addProperty("id",id);r.addProperty("name",name);r.addProperty("UUID",uuid.toString());r.addProperty("title","§a測試稱號");return r;}
 private Path root()throws Exception{var base=Path.of(".build-tools/tests");Files.createDirectories(base);return Files.createTempDirectory(base,"staged-").toAbsolutePath();}
 @Test public void conflictsAndPlanEvidenceNeverChooseIdentity(){var rows=new JsonArray();UUID a=UUID.randomUUID(),b=UUID.randomUUID();rows.add(row(1,"Same",a));rows.add(row(2,"same",b));rows.add(row(3,"Other",a));var missing=row(4,"Missing",b);missing.addProperty("UUID","");rows.add(missing);var plan=new JsonArray();var p=new JsonObject();p.addProperty("uuid",b.toString());p.addProperty("name","Same");plan.add(p);var audit=IdentityAudit.inspect(rows,plan);assertEquals(4,audit.conflicts().size());assertEquals(0,audit.accepted().size());assertFalse(audit.ready());assertFalse(audit.report().get("automaticMerge").getAsBoolean());assertEquals("",rows.get(3).getAsJsonObject().get("UUID").getAsString());}
 @Test public void backgroundStageReopensAndActivationRejectsNewSource()throws Exception{for(var backend:Backend.values()){var root=root();var rows=new JsonArray();UUID uuid=UUID.randomUUID();rows.add(row(1,"Fixture",uuid));rows.add(row(2,"Another",UUID.randomUUID()));Path source=root.resolve("source.json"),stage=root.resolve("stage");Files.writeString(source,rows.toString());var result=StagedProfileMigration.startAsync(source,backend,stage,1,1).get(10,TimeUnit.SECONDS);assertEquals("ready",result.status());assertFalse(Files.exists(root.resolve("production")));Path data=StagedProfileMigration.verifyReady(stage,source,backend);try(var repo=ProfileRepository.open(new StoreConfig(backend,data,1),4)){assertEquals("§a測試稱號",repo.find(uuid).orElseThrow().title());repo.updateTitle(uuid,"新稱號").get();assertEquals("新稱號",repo.find(uuid).orElseThrow().title());}assertThrows(IllegalStateException.class,()->StagedProfileMigration.verifyReady(stage,source,backend));}}
 @Test public void resumeAndConflictStageCannotActivate()throws Exception{var root=root();var rows=new JsonArray();rows.add(row(1,"Good",UUID.randomUUID()));var bad=row(2,"Bad",UUID.randomUUID());bad.addProperty("UUID","");rows.add(bad);Path source=root.resolve("source.json"),stage=root.resolve("stage");Files.writeString(source,rows.toString());var first=StagedProfileMigration.run(source,Backend.SQLITE,stage,1,0,new JsonArray());assertEquals("blocked-conflicts",first.status());var again=StagedProfileMigration.run(source,Backend.SQLITE,stage,1,0,new JsonArray());assertEquals(1,again.completed());assertThrows(IllegalStateException.class,()->StagedProfileMigration.verifyReady(stage,source,Backend.SQLITE));rows.get(0).getAsJsonObject().addProperty("title","changed");Files.writeString(source,rows.toString());assertThrows(IllegalStateException.class,()->StagedProfileMigration.run(source,Backend.SQLITE,stage,1,0,new JsonArray()));}
 @Test public void titleFieldBackwardCompatibleAndQueuedUpdatesKeepOtherFields()throws Exception{var root=root();UUID uuid=UUID.randomUUID();var original=new dev.toka.profiles.model.Profile(uuid,"Fixture",Set.of("Old"),Map.of("firstWindowDate","20261014"),"1");var old=ProfileCodec.encode(original);old.remove("title");assertEquals("",ProfileCodec.decode(old).title());try(var repo=ProfileRepository.open(new StoreConfig(Backend.SQLITE,root.resolve("data"),1),4)){repo.put(original).get();var one=repo.updateTitle(uuid,"first");var two=repo.updateTitle(uuid,"second");one.get();two.get();assertEquals("second",repo.find(uuid).orElseThrow().title());assertEquals(original.preferences(),repo.find(uuid).orElseThrow().preferences());assertThrows(java.util.concurrent.ExecutionException.class,()->repo.updateTitle(UUID.randomUUID(),"none").get());}}
}
